window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-25b96e3201f588af"]={"versions": [{"id": "FIG-25b96e3201f588af", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketformat-Diagramm (Bitfeld-/Header-Layout) für die IPv4-Endpoint-Option im Kontext des AUTOSAR Service Discovery (SOME/IP-SD) Protokolls innerhalb des AUTOSAR-Kommunikationsstacks (BswM, SoAd, TcpIp). Das Format definiert die serielle Bytestruktur zur Übermittlung von IPv4-Netzwerkadressen und Portkonfigurationen für angebotene oder angeforderte Dienste.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das 32-Bit breite Datenfeld gliedert sich in folgende Entitäten:</p>\n<ul class=\"fig-list\"><li><strong>Bit 0–15</strong>: <code>Length</code> (16 Bit, fester Wert <code>0x0009</code>) – Längenangabe der Option in Bytes abzüglich des Length-Felds selbst.\n</li><li><strong>Bit 16–23</strong>: <code>Type</code> (8 Bit, fester Wert <code>0x24</code>) – Typkennung für die IPv4 SD Endpoint Option.\n</li><li><strong>Bit 24–31</strong>: <code>Reserved</code> (8 Bit, fester Wert <code>0x00</code>) – Reserviertes Byte.\n</li><li><strong>Bit 32–63 (Zeile 2)</strong>: <code>IPv4-Address [32bit]</code> (32 Bit) – IPv4-Unicast- oder Multicast-Adresse des Endpunkts.\n</li><li><strong>Bit 64–71</strong>: <code>Reserved</code> (8 Bit, fester Wert <code>0x00</code>) – Reserviertes Byte vor dem Transportprotokoll.\n</li><li><strong>Bit 72–79</strong>: <code>L4-Proto (UDP/…)</code> (8 Bit) – Layer-4-Transportprotokoll (z. B. UDP: <code>0x11</code>, TCP: <code>0x06</code>).\n</li><li><strong>Bit 80–95</strong>: <code>Port Number</code> (16 Bit) – Portnummer des Dienst-Endpunkts.\n</li></ul>\n<p class=\"fig-p\">Eine vertikale Maßlinie an der rechten Seite kennzeichnet die Spanne von Byte 2 bis Ende („Covered by Length (incl. Reserved)“).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Option wird als Teil eines SOME/IP-SD-Nachrichtenpakets serialisiert und über das Netzwerk übertragen. Beim Empfang wertet der SOME/IP-SD-Parser das Feld <code>Length</code> (9 Bytes) und <code>Type</code> (<code>0x24</code>) aus. Bei Übereinstimmung werden die 32-Bit-IPv4-Adresse, das Transportprotokoll (L4-Proto) und die Portnummer extrahiert, um die Socket-Verbindung zur Service-Instanz bzw. dem Eventgroup-Kanal herzustellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Serialisierungsreihenfolge</strong>: Network Byte Order (Big-Endian).\n</li><li><strong>Längenfeld</strong>: <code>Length</code> umfasst genau 9 Oktette (Type-Feld, 1. Reserved-Feld, IPv4-Adresse, 2. Reserved-Feld, L4-Proto und Port Number); das Length-Feld selbst ist nicht in der Längenberechnung enthalten.\n</li><li><strong>Konstanten &amp; Validierung</strong>: <code>Type</code> muss zwingend <code>0x24</code> sein. Beide <code>Reserved</code>-Felder müssen senderseitig mit <code>0x00</code> belegt und empfängerseitig ignoriert bzw. auf <code>0x00</code> validiert werden.\n</li><li><strong>Transportprotokolle</strong>: Typischerweise UDP (<code>0x11</code>) oder TCP (<code>0x06</code>) gemäß IANA-Zuweisung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-bba1a3206103dba9", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketformat-Diagramm (Bitfeld-/Header-Layout) für die IPv4-Endpoint-Option im Kontext des AUTOSAR Service Discovery (SOME/IP-SD) Protokolls innerhalb des AUTOSAR-Kommunikationsstacks (BswM, SoAd, TcpIp). Das Format definiert die serielle Bytestruktur zur Übermittlung von IPv4-Netzwerkadressen und Portkonfigurationen für angebotene oder angeforderte Dienste.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das 32-Bit breite Datenfeld gliedert sich in folgende Entitäten:</p>\n<ul class=\"fig-list\"><li><strong>Bit 0–15</strong>: <code>Length</code> (16 Bit, fester Wert <code>0x0009</code>) – Längenangabe der Option in Bytes abzüglich des Length-Felds selbst.\n</li><li><strong>Bit 16–23</strong>: <code>Type</code> (8 Bit, fester Wert <code>0x24</code>) – Typkennung für die IPv4 SD Endpoint Option.\n</li><li><strong>Bit 24–31</strong>: <code>Reserved</code> (8 Bit, fester Wert <code>0x00</code>) – Reserviertes Byte.\n</li><li><strong>Bit 32–63 (Zeile 2)</strong>: <code>IPv4-Address [32bit]</code> (32 Bit) – IPv4-Unicast- oder Multicast-Adresse des Endpunkts.\n</li><li><strong>Bit 64–71</strong>: <code>Reserved</code> (8 Bit, fester Wert <code>0x00</code>) – Reserviertes Byte vor dem Transportprotokoll.\n</li><li><strong>Bit 72–79</strong>: <code>L4-Proto (UDP/…)</code> (8 Bit) – Layer-4-Transportprotokoll (z. B. UDP: <code>0x11</code>, TCP: <code>0x06</code>).\n</li><li><strong>Bit 80–95</strong>: <code>Port Number</code> (16 Bit) – Portnummer des Dienst-Endpunkts.\n</li></ul>\n<p class=\"fig-p\">Eine vertikale Maßlinie an der rechten Seite kennzeichnet die Spanne von Byte 2 bis Ende („Covered by Length (incl. Reserved)“).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Option wird als Teil eines SOME/IP-SD-Nachrichtenpakets serialisiert und über das Netzwerk übertragen. Beim Empfang wertet der SOME/IP-SD-Parser das Feld <code>Length</code> (9 Bytes) und <code>Type</code> (<code>0x24</code>) aus. Bei Übereinstimmung werden die 32-Bit-IPv4-Adresse, das Transportprotokoll (L4-Proto) und die Portnummer extrahiert, um die Socket-Verbindung zur Service-Instanz bzw. dem Eventgroup-Kanal herzustellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Serialisierungsreihenfolge</strong>: Network Byte Order (Big-Endian).\n</li><li><strong>Längenfeld</strong>: <code>Length</code> umfasst genau 9 Oktette (Type-Feld, 1. Reserved-Feld, IPv4-Adresse, 2. Reserved-Feld, L4-Proto und Port Number); das Length-Feld selbst ist nicht in der Längenberechnung enthalten.\n</li><li><strong>Konstanten &amp; Validierung</strong>: <code>Type</code> muss zwingend <code>0x24</code> sein. Beide <code>Reserved</code>-Felder müssen senderseitig mit <code>0x00</code> belegt und empfängerseitig ignoriert bzw. auf <code>0x00</code> validiert werden.\n</li><li><strong>Transportprotokolle</strong>: Typischerweise UDP (<code>0x11</code>) oder TCP (<code>0x06</code>) gemäß IANA-Zuweisung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-25b96e3201f588af", "to": "FIG-bba1a3206103dba9", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
